"""Offline HTTP helpers built on urllib3: retry policy, pool manager, response parsing."""
import io
import json

import urllib3
from urllib3.response import HTTPResponse
from urllib3.util.retry import Retry

IDEMPOTENT = ["GET", "HEAD", "PUT"]


def build_retry(total=3, backoff=0.5):
    return Retry(
        total=total,
        backoff_factor=backoff,
        status_forcelist=[502, 503, 504],
        method_whitelist=IDEMPOTENT,
    )


def default_methods():
    return sorted(Retry.DEFAULT_METHOD_WHITELIST)


def build_manager(retry=None):
    retry = retry or build_retry()
    timeout = urllib3.Timeout(connect=2.0, read=5.0)
    return urllib3.PoolManager(num_pools=4, maxsize=2, retries=retry, timeout=timeout)


def fake_response(body, status=200, headers=None):
    """Build a response the way a mock transport would, from an in-memory body."""
    return HTTPResponse(body=io.BytesIO(body), headers=headers or {}, status=status)


def json_response(payload, status=200):
    body = json.dumps(payload).encode("utf-8")
    return fake_response(body, status, {"Content-Type": "application/json", "X-Request-Id": "r-1"})


def content_type(resp):
    return resp.getheader("Content-Type", "text/plain")


def header_map(resp):
    return {k.lower(): v for k, v in resp.getheaders().items()}


def parse_json(resp):
    if content_type(resp).startswith("application/json"):
        return json.loads(resp.data.decode("utf-8"))
    return None


def split_url(url):
    scheme, host, port = urllib3.get_host(url)
    return {"scheme": scheme, "host": host, "port": port}


def should_retry(retry, method, status):
    return retry.is_retry(method, status)

