def gzip_response(payload):
    import gzip

    body = gzip.compress(payload)
    headers = {"Content-Encoding": "gzip", "Content-Length": str(len(body))}
    return HTTPResponse(body=io.BytesIO(body), headers=headers, preload_content=False)


def chunk_sizes(resp, amt=7):
    """Sizes of the pieces a consumer sees when it streams a (possibly gzipped) body."""
    return [len(chunk) for chunk in resp.stream(amt)]

def test_chunk_sizes_cover_body():
    payload = b"hello world " * 10
    assert sum(client.chunk_sizes(client.gzip_response(payload))) == len(payload)
